# usage: run.sh ARM SEED FRAMES  (ARM: new | old | noeat)
cd /home/user/cloud
S=/tmp/claude-0/-home-user-Pixel-Physics/e58654de-422f-584a-a4c1-44fcef22179d/scratchpad/fl
A=$1; SD=$2; F=$3; G=scratch/inrun/genomes/h1.raw.txt; E=""
[ $A = old ] && E="PP_NOMIND=1"
case $A in hA_*) G=$S/cp/${A#hA_}.txt; E="PP_PACK=1 PP_CARRY=1 PP_CARRY_HUNGRYONLY=1 PP_CARRY_ANYCUT=1 PP_CARRY_HUNGRY=2.5";; hB_*) G=$S/cp/${A#hB_}.txt; E="PP_PACK=1 PP_CARRY=1 PP_CARRY_HUNGRYONLY=1 PP_CARRY_ANYCUT=1 PP_CARRY_ANYDROP=1 PP_NEEDDROP=1 PP_CARRY_STORE=1 PP_CARRY_HUNGRY=2.5";; sk_*) G=$S/cp/${A#sk_}.txt; E="PP_PACK=1 PP_SYNAPSE_K=0.654";; skh1) E="PP_PACK=1 PP_SYNAPSE_K=1.529";; qh*_c1) H=${A#qh}; H=${H%_c1}; G=$S/cp/c1.txt; E="PP_PACK=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_HUNGRY=$H";; pd*) E="PP_PACK=1 PP_NEEDDROP=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_ANYDROP=1 PP_CARRY_HUNGRY=${A#pd}";; qd_*) G=$S/cp/${A#qd_}.txt; E="PP_PACK=1 PP_NEEDDROP=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_ANYDROP=1 PP_CARRY_HUNGRY=2.5";; nf_*) G=$S/cp/${A#nf_}.txt; E="PP_PACK=1 PP_NOADULTFEED=1";; nfh1) E="PP_PACK=1 PP_NOADULTFEED=1";; nd_*) G=$S/cp/${A#nd_}.txt; E="PP_PACK=1 PP_NEEDDROP=1";; ndh1) E="PP_PACK=1 PP_NEEDDROP=1";; pn*) E="PP_PACK=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_ANYDROP=1 PP_CARRY_WAY=1 PP_CARRY_STORE=1 PP_CARRY_NOEAT=1 PP_CARRY_FLOOR=0 PP_CARRY_HUNGRY=2.5 PP_CARRY_HOME_R=${A#pn}";; ps*) E="PP_PACK=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_ANYDROP=1 PP_CARRY_WAY=1 PP_CARRY_STORE=1 PP_CARRY_HUNGRY=2.5 PP_CARRY_HOME_R=${A#ps}";; pw*) E="PP_PACK=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_ANYDROP=1 PP_CARRY_WAY=1 PP_CARRY_HUNGRY=2.5 PP_CARRY_HOME_R=${A#pw}";; pa*) E="PP_PACK=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_ANYDROP=1 PP_CARRY_HUNGRY=2.5 PP_CARRY_HOME_R=${A#pa}";; ph*) E="PP_PACK=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_HUNGRY=2.5 PP_CARRY_HOME_R=${A#ph}";; cp_*) G=$S/cp/${A#cp_}.txt; E="PP_PACK=1";; eat*) E="PP_EAT_BELOW=${A#eat}";; carry*) E="PP_CARRY=${A#carry}";; ch*) E="PP_CARRY=1 PP_CARRY_HUNGRY=${A#ch}";; px*) E="PP_PACK=1 PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_HUNGRY=${A#px}";; pk*) E="PP_PACK=1 PP_CARRY=0";; cx*) E="PP_CARRY=1 PP_CARRY_ANYCUT=1 PP_CARRY_HUNGRY=${A#cx}";; esac
[ $A = noeat ] && G=$S/h1-noeat.raw.txt
CTL="min_age=8000 cooldown=3000 w_deliver=7 w_field=0.05 w_depth=2 rim=15 cap=60 fresh_kid=1 drip=20 mutation=neutral kevents=10 w_home_eat=2 kid_cap=4 retire=1 hall=30000 fprice=tank w_hungry=10 progress=1 turn=30000"
rm -rf $S/l/$A$SD; mkdir -p $S/l
env RAYON_NUM_THREADS=1 $E target/release/examples/inrun founders=$G:1 mutants=30:0.03:1.0:7 seed=$SD frames=$F dist=25 spread=10 grants=3 window=4000 sel=off $CTL trace=50 out=$S/l/$A$SD > $S/l/$A$SD.log 2>&1
rm -f $S/l/$A$SD/map_* $S/l/$A$SD/ants_f*
